// Assemble a grounded prompt context. Customer messages and retrieved documents
// are untrusted data - the system message in the agent handles injection defense.
const envelope = $input.first().json;

const rag = envelope.rag || { top_context: '', strong: false, miss: false };
const memory = envelope.memory || { summary: '' };
const classification = envelope.classification || { intent: 'unknown', confidence: 0 };
const sentiment = envelope.sentiment || { sentiment: 'neutral', priority: 'normal' };
const policy = envelope.policy || { priority: 'normal' };
const mode = envelope.generation_mode || 'answer';
const issues = Array.isArray(envelope.validation_issues) ? envelope.validation_issues : [];

const ragNotice = rag.strong
  ? ''
  : '\nWARNING: retrieved knowledge is weak or missing. If you cannot answer from the context, say so and ask a clarifying question or offer to escalate.';

const contextLines = [
  'CUSTOMER MESSAGE:',
  envelope.message || '',
  '',
  'INTENT: ' + (classification.intent || 'unknown'),
  'SENTIMENT: ' + (sentiment.sentiment || 'neutral'),
  'PRIORITY: ' + (sentiment.priority || policy.priority || 'normal'),
  '',
  'CONVERSATION SUMMARY:',
  memory.summary || '(none)',
  '',
  'KNOWLEDGE BASE CONTEXT (authoritative, use ONLY this):',
  rag.top_context || '(no relevant knowledge found)',
  ragNotice
].join('\n');

let guidance = '';
if (mode === 'clarify') {
  guidance = '\nINSTRUCTION: You do not have enough knowledge to answer this question. Ask ONE concise clarifying question, or tell the customer you are routing them to a human agent. Do not guess.';
} else if (mode === 'regen') {
  guidance = '\nINSTRUCTION: Your previous response failed automated validation. Fix the specific issues listed below and rewrite the response.';
}

if (issues.length) {
  guidance += '\nVALIDATION ISSUES TO FIX:\n- ' + issues.join('\n- ');
}

const promptContext = contextLines + guidance;
return [{ json: { ...envelope, promptContext } }];

try {
  const ctx = ($json && $json.rag && $json.rag.top_context) || '';
  if (ctx) {
    return `Authoritative knowledge base excerpts for this conversation:\n\n${ctx}`;
  }
  return 'No knowledge base context is available for this query. Answer that you cannot confirm the information and ask a clarifying question or offer to escalate.';
} catch (e) {
  return 'Knowledge base lookup failed. Do not guess; ask a clarifying question or offer to escalate.';
}

const envelope = $('When Called by Another Workflow').first().json;
const output = ($input.first().json.output || '').trim();
const regenerated = envelope.generation_mode === 'regen';
return [{ json: { ...envelope, response: { text: output, mode: envelope.generation_mode || 'answer', regenerated } } }];
